-- =====================================================================
--  메일 템플릿 관리 DDL  /  Oracle 11g 이상
--
--  설계문서: docs/mail-template-설계.md
--  MySQL 판과 컬럼 구성 동일. Oracle 특성만 반영:
--    - AUTO_INCREMENT  -> SEQUENCE + BEFORE INSERT TRIGGER (11g 호환)
--      (12c 이상이면 GENERATED BY DEFAULT AS IDENTITY 로 트리거 제거 가능 - 주석 참조)
--    - LONGTEXT        -> CLOB
--    - DATETIME        -> DATE  (초 단위 이상 정밀도 필요 시 TIMESTAMP)
--    - COMMENT 인라인  -> COMMENT ON COLUMN 문 분리
--    - ON UPDATE CURRENT_TIMESTAMP 없음 -> 애플리케이션(JPA @PreUpdate)에서 세팅
-- =====================================================================

-- ---------------------------------------------------------------------
-- DROP (개발 편의. 운영 반영 시 제거)
-- ---------------------------------------------------------------------
-- DROP VIEW  V_MAIL_DISPATCH_MAP;
-- DROP TABLE MAIL_SEND_LOG        CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_EVENT_RECIPIENT CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_EVENT_TEMPLATE  CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_EVENT           CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_TEMPLATE_ATTACH CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_TEMPLATE_VAR    CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_TEMPLATE_VERSION CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_TEMPLATE        CASCADE CONSTRAINTS;
-- DROP TABLE MAIL_TEMPLATE_LAYOUT CASCADE CONSTRAINTS;
-- DROP SEQUENCE SEQ_MAIL_TEMPLATE_LAYOUT;
-- DROP SEQUENCE SEQ_MAIL_TEMPLATE;
-- DROP SEQUENCE SEQ_MAIL_TEMPLATE_VERSION;
-- DROP SEQUENCE SEQ_MAIL_TEMPLATE_VAR;
-- DROP SEQUENCE SEQ_MAIL_TEMPLATE_ATTACH;
-- DROP SEQUENCE SEQ_MAIL_EVENT;
-- DROP SEQUENCE SEQ_MAIL_EVENT_TEMPLATE;
-- DROP SEQUENCE SEQ_MAIL_EVENT_RECIPIENT;
-- DROP SEQUENCE SEQ_MAIL_SEND_LOG;


-- ---------------------------------------------------------------------
-- 1. MAIL_TEMPLATE_LAYOUT : 공통 레이아웃(헤더/푸터/기본CSS)
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_TEMPLATE_LAYOUT (
    LAYOUT_ID       NUMBER(19)      NOT NULL,
    LAYOUT_CODE     VARCHAR2(60)    NOT NULL,
    LAYOUT_NAME     VARCHAR2(150)   NOT NULL,
    HEADER_HTML     CLOB,
    FOOTER_HTML     CLOB,
    BASE_CSS        CLOB,
    BODY_WIDTH      NUMBER(5)       DEFAULT 600 NOT NULL,
    DESCRIPTION     VARCHAR2(500),
    USE_YN          CHAR(1)         DEFAULT 'Y' NOT NULL,
    REG_ID          VARCHAR2(50),
    REG_DT          DATE            DEFAULT SYSDATE NOT NULL,
    UPD_ID          VARCHAR2(50),
    UPD_DT          DATE,
    CONSTRAINT PK_MAIL_TEMPLATE_LAYOUT PRIMARY KEY (LAYOUT_ID),
    CONSTRAINT UK_MAIL_LAYOUT_CODE UNIQUE (LAYOUT_CODE),
    CONSTRAINT CK_MAIL_LAYOUT_USE CHECK (USE_YN IN ('Y','N'))
);
COMMENT ON TABLE  MAIL_TEMPLATE_LAYOUT              IS '메일 공통 레이아웃';
COMMENT ON COLUMN MAIL_TEMPLATE_LAYOUT.LAYOUT_ID    IS '레이아웃 ID';
COMMENT ON COLUMN MAIL_TEMPLATE_LAYOUT.LAYOUT_CODE  IS '레이아웃 코드 (예: DEFAULT_KO)';
COMMENT ON COLUMN MAIL_TEMPLATE_LAYOUT.HEADER_HTML  IS '상단 공통 HTML (로고/CI)';
COMMENT ON COLUMN MAIL_TEMPLATE_LAYOUT.FOOTER_HTML  IS '하단 공통 HTML (법적고지/수신거부)';
COMMENT ON COLUMN MAIL_TEMPLATE_LAYOUT.BASE_CSS     IS '기본 CSS (인라이너 입력용)';
COMMENT ON COLUMN MAIL_TEMPLATE_LAYOUT.BODY_WIDTH   IS '본문 최대 폭(px)';

CREATE SEQUENCE SEQ_MAIL_TEMPLATE_LAYOUT START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_TEMPLATE_LAYOUT_ID
BEFORE INSERT ON MAIL_TEMPLATE_LAYOUT FOR EACH ROW
WHEN (NEW.LAYOUT_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_TEMPLATE_LAYOUT.NEXTVAL INTO :NEW.LAYOUT_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 2. MAIL_TEMPLATE : 템플릿 마스터
--    본문은 여기 없다. CURRENT_VERSION_ID 로 활성 버전만 가리킨다.
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_TEMPLATE (
    TEMPLATE_ID         NUMBER(19)      NOT NULL,
    TEMPLATE_CODE       VARCHAR2(60)    NOT NULL,
    TEMPLATE_NAME       VARCHAR2(150)   NOT NULL,
    CATEGORY_CODE       VARCHAR2(30)    NOT NULL,
    ENGINE_TYPE         VARCHAR2(20)    DEFAULT 'VELOCITY' NOT NULL,
    LOCALE_CODE         VARCHAR2(10)    DEFAULT 'ko_KR'    NOT NULL,
    LAYOUT_ID           NUMBER(19),
    STATUS_CODE         VARCHAR2(20)    DEFAULT 'DRAFT'    NOT NULL,
    CURRENT_VERSION_ID  NUMBER(19),
    OWNER_DEPT_CODE     VARCHAR2(30),
    OWNER_USER_ID       VARCHAR2(50),
    DESCRIPTION         VARCHAR2(500),
    THUMB_URL           VARCHAR2(300),
    TAGS                VARCHAR2(300),
    USE_YN              CHAR(1)         DEFAULT 'Y' NOT NULL,
    DEL_YN              CHAR(1)         DEFAULT 'N' NOT NULL,
    REG_ID              VARCHAR2(50),
    REG_DT              DATE            DEFAULT SYSDATE NOT NULL,
    UPD_ID              VARCHAR2(50),
    UPD_DT              DATE,
    CONSTRAINT PK_MAIL_TEMPLATE PRIMARY KEY (TEMPLATE_ID),
    CONSTRAINT UK_MAIL_TPL_CODE UNIQUE (TEMPLATE_CODE),
    CONSTRAINT FK_MAIL_TPL_LAYOUT FOREIGN KEY (LAYOUT_ID)
        REFERENCES MAIL_TEMPLATE_LAYOUT (LAYOUT_ID),
    CONSTRAINT CK_MAIL_TPL_ENGINE CHECK (ENGINE_TYPE IN ('VELOCITY','THYMELEAF','PLAIN')),
    CONSTRAINT CK_MAIL_TPL_STATUS CHECK (STATUS_CODE IN ('DRAFT','REVIEW','ACTIVE','ARCHIVED')),
    CONSTRAINT CK_MAIL_TPL_USE    CHECK (USE_YN IN ('Y','N')),
    CONSTRAINT CK_MAIL_TPL_DEL    CHECK (DEL_YN IN ('Y','N'))
);
COMMENT ON TABLE  MAIL_TEMPLATE                     IS '메일 템플릿 마스터';
COMMENT ON COLUMN MAIL_TEMPLATE.TEMPLATE_CODE       IS '템플릿 코드 (업무키, 예: ORDER_CONFIRM_KO)';
COMMENT ON COLUMN MAIL_TEMPLATE.CATEGORY_CODE       IS '카테고리 ACCOUNT/ORDER/APPROVAL/NOTICE/MARKETING';
COMMENT ON COLUMN MAIL_TEMPLATE.ENGINE_TYPE         IS '렌더 엔진 VELOCITY/THYMELEAF/PLAIN';
COMMENT ON COLUMN MAIL_TEMPLATE.STATUS_CODE         IS '상태 DRAFT/REVIEW/ACTIVE/ARCHIVED';
COMMENT ON COLUMN MAIL_TEMPLATE.CURRENT_VERSION_ID  IS '현재 활성 버전 ID';
COMMENT ON COLUMN MAIL_TEMPLATE.DEL_YN              IS '논리 삭제 여부';

CREATE INDEX IX_MAIL_TPL_CATEGORY ON MAIL_TEMPLATE (CATEGORY_CODE, STATUS_CODE);
CREATE INDEX IX_MAIL_TPL_LAYOUT   ON MAIL_TEMPLATE (LAYOUT_ID);

CREATE SEQUENCE SEQ_MAIL_TEMPLATE START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_TEMPLATE_ID
BEFORE INSERT ON MAIL_TEMPLATE FOR EACH ROW
WHEN (NEW.TEMPLATE_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_TEMPLATE.NEXTVAL INTO :NEW.TEMPLATE_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 3. MAIL_TEMPLATE_VERSION : 본문 버전 이력 (수정 = 새 행)
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_TEMPLATE_VERSION (
    VERSION_ID      NUMBER(19)      NOT NULL,
    TEMPLATE_ID     NUMBER(19)      NOT NULL,
    VERSION_NO      NUMBER(6)       NOT NULL,
    SUBJECT         VARCHAR2(300)   NOT NULL,
    PREHEADER       VARCHAR2(200),
    BODY_HTML       CLOB            NOT NULL,
    BODY_TEXT       CLOB,
    ENGINE_TYPE     VARCHAR2(20)    DEFAULT 'VELOCITY' NOT NULL,
    LAYOUT_ID       NUMBER(19),
    STATUS_CODE     VARCHAR2(20)    DEFAULT 'DRAFT' NOT NULL,
    CHANGE_NOTE     VARCHAR2(500),
    BODY_CHECKSUM   VARCHAR2(64),
    APPROVED_BY     VARCHAR2(50),
    APPROVED_DT     DATE,
    REG_ID          VARCHAR2(50),
    REG_DT          DATE            DEFAULT SYSDATE NOT NULL,
    CONSTRAINT PK_MAIL_TEMPLATE_VERSION PRIMARY KEY (VERSION_ID),
    CONSTRAINT UK_MAIL_VER_NO UNIQUE (TEMPLATE_ID, VERSION_NO),
    CONSTRAINT FK_MAIL_VER_TPL FOREIGN KEY (TEMPLATE_ID)
        REFERENCES MAIL_TEMPLATE (TEMPLATE_ID) ON DELETE CASCADE,
    CONSTRAINT CK_MAIL_VER_STATUS CHECK (STATUS_CODE IN ('DRAFT','ACTIVE','ARCHIVED'))
);
COMMENT ON TABLE  MAIL_TEMPLATE_VERSION                 IS '메일 템플릿 본문 버전';
COMMENT ON COLUMN MAIL_TEMPLATE_VERSION.SUBJECT         IS '메일 제목 (치환식 사용 가능)';
COMMENT ON COLUMN MAIL_TEMPLATE_VERSION.PREHEADER       IS '프리헤더 (받은편지함 미리보기 문구)';
COMMENT ON COLUMN MAIL_TEMPLATE_VERSION.BODY_HTML       IS 'HTML 본문 (Velocity/Thymeleaf 문법 포함)';
COMMENT ON COLUMN MAIL_TEMPLATE_VERSION.BODY_TEXT       IS 'text/plain 대체 본문';
COMMENT ON COLUMN MAIL_TEMPLATE_VERSION.CHANGE_NOTE     IS '변경 사유';
COMMENT ON COLUMN MAIL_TEMPLATE_VERSION.BODY_CHECKSUM   IS '본문 SHA-256 (중복 버전 방지)';

CREATE INDEX IX_MAIL_VER_TPL ON MAIL_TEMPLATE_VERSION (TEMPLATE_ID, STATUS_CODE);

CREATE SEQUENCE SEQ_MAIL_TEMPLATE_VERSION START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_TEMPLATE_VERSION_ID
BEFORE INSERT ON MAIL_TEMPLATE_VERSION FOR EACH ROW
WHEN (NEW.VERSION_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_TEMPLATE_VERSION.NEXTVAL INTO :NEW.VERSION_ID FROM DUAL;
END;
/

-- 마스터 -> 현재버전 FK (순환 참조이므로 테이블 생성 후 추가)
ALTER TABLE MAIL_TEMPLATE
    ADD CONSTRAINT FK_MAIL_TPL_CURVER FOREIGN KEY (CURRENT_VERSION_ID)
        REFERENCES MAIL_TEMPLATE_VERSION (VERSION_ID);


-- ---------------------------------------------------------------------
-- 4. MAIL_TEMPLATE_VAR : 템플릿 변수 정의
--    테스트발송 폼 자동생성 + 발송 전 필수값 검증의 근거.
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_TEMPLATE_VAR (
    VAR_ID          NUMBER(19)      NOT NULL,
    TEMPLATE_ID     NUMBER(19)      NOT NULL,
    VAR_NAME        VARCHAR2(60)    NOT NULL,
    VAR_PATH        VARCHAR2(200),
    DATA_TYPE       VARCHAR2(20)    DEFAULT 'STRING' NOT NULL,
    REQUIRED_YN     CHAR(1)         DEFAULT 'N' NOT NULL,
    SAMPLE_VALUE    VARCHAR2(1000),
    DESCRIPTION     VARCHAR2(300),
    SORT_ORDER      NUMBER(5)       DEFAULT 0 NOT NULL,
    CONSTRAINT PK_MAIL_TEMPLATE_VAR PRIMARY KEY (VAR_ID),
    CONSTRAINT UK_MAIL_VAR UNIQUE (TEMPLATE_ID, VAR_NAME),
    CONSTRAINT FK_MAIL_VAR_TPL FOREIGN KEY (TEMPLATE_ID)
        REFERENCES MAIL_TEMPLATE (TEMPLATE_ID) ON DELETE CASCADE,
    CONSTRAINT CK_MAIL_VAR_TYPE CHECK (DATA_TYPE IN ('STRING','NUMBER','DATE','BOOLEAN','LIST','OBJECT','URL')),
    CONSTRAINT CK_MAIL_VAR_REQ  CHECK (REQUIRED_YN IN ('Y','N'))
);
COMMENT ON TABLE  MAIL_TEMPLATE_VAR                 IS '메일 템플릿 변수 정의';
COMMENT ON COLUMN MAIL_TEMPLATE_VAR.VAR_NAME        IS '변수명 (예: userName)';
COMMENT ON COLUMN MAIL_TEMPLATE_VAR.VAR_PATH        IS '실제 표현식 (예: ${order.items[].name})';
COMMENT ON COLUMN MAIL_TEMPLATE_VAR.REQUIRED_YN     IS '필수여부 - Y 인데 값 없으면 발송 중단';
COMMENT ON COLUMN MAIL_TEMPLATE_VAR.SAMPLE_VALUE    IS '미리보기/테스트 기본값';

CREATE SEQUENCE SEQ_MAIL_TEMPLATE_VAR START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_TEMPLATE_VAR_ID
BEFORE INSERT ON MAIL_TEMPLATE_VAR FOR EACH ROW
WHEN (NEW.VAR_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_TEMPLATE_VAR.NEXTVAL INTO :NEW.VAR_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 5. MAIL_TEMPLATE_ATTACH : 고정 첨부 / 인라인 이미지(CID)
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_TEMPLATE_ATTACH (
    ATTACH_ID       NUMBER(19)      NOT NULL,
    TEMPLATE_ID     NUMBER(19)      NOT NULL,
    ATTACH_TYPE     VARCHAR2(20)    DEFAULT 'FILE' NOT NULL,
    CID             VARCHAR2(60),
    FILE_NAME       VARCHAR2(255)   NOT NULL,
    FILE_PATH       VARCHAR2(500)   NOT NULL,
    CONTENT_TYPE    VARCHAR2(100),
    FILE_SIZE       NUMBER(19),
    SORT_ORDER      NUMBER(5)       DEFAULT 0 NOT NULL,
    USE_YN          CHAR(1)         DEFAULT 'Y' NOT NULL,
    CONSTRAINT PK_MAIL_TEMPLATE_ATTACH PRIMARY KEY (ATTACH_ID),
    CONSTRAINT FK_MAIL_ATTACH_TPL FOREIGN KEY (TEMPLATE_ID)
        REFERENCES MAIL_TEMPLATE (TEMPLATE_ID) ON DELETE CASCADE,
    CONSTRAINT CK_MAIL_ATTACH_TYPE CHECK (ATTACH_TYPE IN ('FILE','INLINE'))
);
COMMENT ON TABLE  MAIL_TEMPLATE_ATTACH      IS '메일 템플릿 첨부/인라인 이미지';
COMMENT ON COLUMN MAIL_TEMPLATE_ATTACH.CID  IS 'Content-ID (INLINE 인 경우 본문에서 cid:로 참조)';

CREATE INDEX IX_MAIL_ATTACH_TPL ON MAIL_TEMPLATE_ATTACH (TEMPLATE_ID);

CREATE SEQUENCE SEQ_MAIL_TEMPLATE_ATTACH START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_TEMPLATE_ATTACH_ID
BEFORE INSERT ON MAIL_TEMPLATE_ATTACH FOR EACH ROW
WHEN (NEW.ATTACH_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_TEMPLATE_ATTACH.NEXTVAL INTO :NEW.ATTACH_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 6. MAIL_EVENT : 메일 발송 지점(이벤트)
--    소스코드가 참조하는 불변 키. 템플릿을 갈아끼워도 이 코드는 안 바뀐다.
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_EVENT (
    EVENT_ID        NUMBER(19)      NOT NULL,
    EVENT_CODE      VARCHAR2(60)    NOT NULL,
    EVENT_NAME      VARCHAR2(150)   NOT NULL,
    MODULE_CODE     VARCHAR2(30)    NOT NULL,
    TRIGGER_TYPE    VARCHAR2(20)    DEFAULT 'EVENT'  NOT NULL,
    SEND_CHANNEL    VARCHAR2(20)    DEFAULT 'EMAIL'  NOT NULL,
    IMPORTANCE      VARCHAR2(20)    DEFAULT 'NORMAL' NOT NULL,
    DESCRIPTION     VARCHAR2(500),
    SOURCE_HINT     VARCHAR2(300),
    USE_YN          CHAR(1)         DEFAULT 'Y' NOT NULL,
    REG_DT          DATE            DEFAULT SYSDATE NOT NULL,
    CONSTRAINT PK_MAIL_EVENT PRIMARY KEY (EVENT_ID),
    CONSTRAINT UK_MAIL_EVENT_CODE UNIQUE (EVENT_CODE),
    CONSTRAINT CK_MAIL_EVENT_TRIGGER CHECK (TRIGGER_TYPE IN ('EVENT','BATCH','MANUAL')),
    CONSTRAINT CK_MAIL_EVENT_CHANNEL CHECK (SEND_CHANNEL IN ('EMAIL','SMS','PUSH'))
);
COMMENT ON TABLE  MAIL_EVENT                IS '메일 발송 이벤트(발송 지점) 정의';
COMMENT ON COLUMN MAIL_EVENT.EVENT_CODE     IS '이벤트 코드 (예: ORDER.CONFIRM)';
COMMENT ON COLUMN MAIL_EVENT.MODULE_CODE    IS '업무 모듈 USER/ORDER/APPROVAL/NOTICE/MARKETING';
COMMENT ON COLUMN MAIL_EVENT.TRIGGER_TYPE   IS '발송 트리거 EVENT(즉시)/BATCH/MANUAL';
COMMENT ON COLUMN MAIL_EVENT.SOURCE_HINT    IS '호출 위치 힌트 (예: OrderService#confirm)';

CREATE INDEX IX_MAIL_EVENT_MODULE ON MAIL_EVENT (MODULE_CODE, USE_YN);

CREATE SEQUENCE SEQ_MAIL_EVENT START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_EVENT_ID
BEFORE INSERT ON MAIL_EVENT FOR EACH ROW
WHEN (NEW.EVENT_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_EVENT.NEXTVAL INTO :NEW.EVENT_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 7. MAIL_EVENT_TEMPLATE : 이벤트 <-> 템플릿 바인딩   ★ 핵심
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_EVENT_TEMPLATE (
    MAP_ID          NUMBER(19)      NOT NULL,
    EVENT_ID        NUMBER(19)      NOT NULL,
    TEMPLATE_ID     NUMBER(19)      NOT NULL,
    LOCALE_CODE     VARCHAR2(10)    DEFAULT 'ko_KR'   NOT NULL,
    BRAND_CODE      VARCHAR2(30)    DEFAULT 'DEFAULT' NOT NULL,
    PRIORITY        NUMBER(5)       DEFAULT 1 NOT NULL,
    VALID_FROM_DT   DATE,
    VALID_TO_DT     DATE,
    FROM_NAME       VARCHAR2(100),
    FROM_EMAIL      VARCHAR2(200),
    REPLY_TO        VARCHAR2(200),
    BCC_LIST        VARCHAR2(1000),
    ACTIVE_YN       CHAR(1)         DEFAULT 'Y' NOT NULL,
    REG_ID          VARCHAR2(50),
    REG_DT          DATE            DEFAULT SYSDATE NOT NULL,
    UPD_ID          VARCHAR2(50),
    UPD_DT          DATE,
    CONSTRAINT PK_MAIL_EVENT_TEMPLATE PRIMARY KEY (MAP_ID),
    CONSTRAINT UK_MAIL_EVT_TPL UNIQUE (EVENT_ID, LOCALE_CODE, BRAND_CODE, PRIORITY),
    CONSTRAINT FK_MAIL_EVT_TPL_EVT FOREIGN KEY (EVENT_ID)
        REFERENCES MAIL_EVENT (EVENT_ID) ON DELETE CASCADE,
    CONSTRAINT FK_MAIL_EVT_TPL_TPL FOREIGN KEY (TEMPLATE_ID)
        REFERENCES MAIL_TEMPLATE (TEMPLATE_ID),
    CONSTRAINT CK_MAIL_EVT_TPL_ACTIVE CHECK (ACTIVE_YN IN ('Y','N'))
);
COMMENT ON TABLE  MAIL_EVENT_TEMPLATE                   IS '메일 이벤트-템플릿 바인딩';
COMMENT ON COLUMN MAIL_EVENT_TEMPLATE.PRIORITY          IS '우선순위 (A/B 테스트 가중치로도 활용)';
COMMENT ON COLUMN MAIL_EVENT_TEMPLATE.VALID_FROM_DT     IS '적용 시작일시 (NULL = 즉시)';
COMMENT ON COLUMN MAIL_EVENT_TEMPLATE.VALID_TO_DT       IS '적용 종료일시 (NULL = 무기한)';
COMMENT ON COLUMN MAIL_EVENT_TEMPLATE.BCC_LIST          IS '상시 BCC (감사 아카이브 주소 등)';

CREATE INDEX IX_MAIL_EVT_TPL_TEMPLATE ON MAIL_EVENT_TEMPLATE (TEMPLATE_ID);
CREATE INDEX IX_MAIL_EVT_TPL_ACTIVE   ON MAIL_EVENT_TEMPLATE (ACTIVE_YN, VALID_FROM_DT, VALID_TO_DT);

CREATE SEQUENCE SEQ_MAIL_EVENT_TEMPLATE START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_EVENT_TEMPLATE_ID
BEFORE INSERT ON MAIL_EVENT_TEMPLATE FOR EACH ROW
WHEN (NEW.MAP_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_EVENT_TEMPLATE.NEXTVAL INTO :NEW.MAP_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 7-1. MAIL_EVENT_RECIPIENT : 수신자 결정 규칙   ★ 핵심
--    "무엇을(템플릿) 언제(이벤트)" 만으로는 부족하다. "누구에게" 가 남는다.
--    이 규칙이 없으면 수신자 결정 로직이 자바 코드에 박히고,
--    "이제 팀장도 CC 넣어줘" 한마디에 재배포가 필요해진다.
--
--    RECIPIENT_TYPE 별 TARGET_VALUE 의미
--      REQUESTER / ASSIGNEE / APPROVER : 대상값 불필요
--      DEPT_HEAD  : 부서 기준 필드명 (비우면 요청자 부서)
--      TEAM       : 부서코드
--      ROLE       : 역할(권한그룹) 코드
--      FIXED      : 고정 이메일 (콤마 구분)
--      EXPRESSION : 모델 표현식
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_EVENT_RECIPIENT (
    RECIPIENT_ID    NUMBER(19)      NOT NULL,
    EVENT_ID        NUMBER(19)      NOT NULL,
    RECIPIENT_TYPE  VARCHAR2(30)    NOT NULL,
    SEND_FIELD      VARCHAR2(10)    DEFAULT 'TO' NOT NULL,
    TARGET_VALUE    VARCHAR2(300),
    CONDITION_EXPR  VARCHAR2(300),
    DESCRIPTION     VARCHAR2(300),
    SORT_ORDER      NUMBER(5)       DEFAULT 0 NOT NULL,
    USE_YN          CHAR(1)         DEFAULT 'Y' NOT NULL,
    REG_ID          VARCHAR2(50),
    REG_DT          DATE            DEFAULT SYSDATE NOT NULL,
    UPD_ID          VARCHAR2(50),
    UPD_DT          DATE,
    CONSTRAINT PK_MAIL_EVENT_RECIPIENT PRIMARY KEY (RECIPIENT_ID),
    CONSTRAINT FK_MAIL_RCPT_EVT FOREIGN KEY (EVENT_ID)
        REFERENCES MAIL_EVENT (EVENT_ID) ON DELETE CASCADE,
    CONSTRAINT CK_MAIL_RCPT_TYPE CHECK (RECIPIENT_TYPE IN
        ('REQUESTER','ASSIGNEE','APPROVER','DEPT_HEAD','TEAM','ROLE','FIXED','EXPRESSION')),
    CONSTRAINT CK_MAIL_RCPT_FIELD CHECK (SEND_FIELD IN ('TO','CC','BCC')),
    CONSTRAINT CK_MAIL_RCPT_USE   CHECK (USE_YN IN ('Y','N'))
);
COMMENT ON TABLE  MAIL_EVENT_RECIPIENT                 IS '메일 이벤트별 수신자 결정 규칙';
COMMENT ON COLUMN MAIL_EVENT_RECIPIENT.RECIPIENT_TYPE  IS 'REQUESTER/ASSIGNEE/APPROVER/DEPT_HEAD/TEAM/ROLE/FIXED/EXPRESSION';
COMMENT ON COLUMN MAIL_EVENT_RECIPIENT.SEND_FIELD      IS '수신 구분 TO/CC/BCC';
COMMENT ON COLUMN MAIL_EVENT_RECIPIENT.TARGET_VALUE    IS '유형별 대상값 (역할코드/부서코드/고정주소/표현식)';
COMMENT ON COLUMN MAIL_EVENT_RECIPIENT.CONDITION_EXPR  IS '조건식 - 참일 때만 수신';

CREATE INDEX IX_MAIL_RCPT_EVT ON MAIL_EVENT_RECIPIENT (EVENT_ID, USE_YN, SORT_ORDER);

CREATE SEQUENCE SEQ_MAIL_EVENT_RECIPIENT START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_EVENT_RECIPIENT_ID
BEFORE INSERT ON MAIL_EVENT_RECIPIENT FOR EACH ROW
WHEN (NEW.RECIPIENT_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_EVENT_RECIPIENT.NEXTVAL INTO :NEW.RECIPIENT_ID FROM DUAL;
END;
/


-- ---------------------------------------------------------------------
-- 8. MAIL_SEND_LOG : 발송 이력 (실발송 + 테스트)
--    VERSION_ID 를 남겨야 "그때 나간 원문"을 재현할 수 있다.
-- ---------------------------------------------------------------------
CREATE TABLE MAIL_SEND_LOG (
    LOG_ID          NUMBER(19)      NOT NULL,
    SEND_TYPE       VARCHAR2(10)    DEFAULT 'REAL' NOT NULL,
    EVENT_ID        NUMBER(19),
    TEMPLATE_ID     NUMBER(19),
    VERSION_ID      NUMBER(19),
    SUBJECT_SNAP    VARCHAR2(300),
    BODY_SNAP       CLOB,
    MERGE_DATA_JSON CLOB,
    FROM_EMAIL      VARCHAR2(200),
    TO_EMAIL        VARCHAR2(200)   NOT NULL,
    TO_NAME         VARCHAR2(100),
    CC_LIST         VARCHAR2(1000),
    BCC_LIST        VARCHAR2(1000),
    STATUS_CODE     VARCHAR2(20)    DEFAULT 'QUEUED' NOT NULL,
    ERROR_CODE      VARCHAR2(50),
    ERROR_MESSAGE   VARCHAR2(1000),
    RETRY_CNT       NUMBER(5)       DEFAULT 0 NOT NULL,
    SMTP_MESSAGE_ID VARCHAR2(200),
    REQ_ID          VARCHAR2(50),
    REQ_DT          DATE            DEFAULT SYSDATE NOT NULL,
    SENT_DT         DATE,
    OPEN_DT         DATE,
    CLICK_DT        DATE,
    CONSTRAINT PK_MAIL_SEND_LOG PRIMARY KEY (LOG_ID),
    CONSTRAINT FK_MAIL_LOG_EVT FOREIGN KEY (EVENT_ID)    REFERENCES MAIL_EVENT (EVENT_ID),
    CONSTRAINT FK_MAIL_LOG_TPL FOREIGN KEY (TEMPLATE_ID) REFERENCES MAIL_TEMPLATE (TEMPLATE_ID),
    CONSTRAINT FK_MAIL_LOG_VER FOREIGN KEY (VERSION_ID)  REFERENCES MAIL_TEMPLATE_VERSION (VERSION_ID),
    CONSTRAINT CK_MAIL_LOG_SENDTYPE CHECK (SEND_TYPE IN ('REAL','TEST')),
    CONSTRAINT CK_MAIL_LOG_STATUS   CHECK (STATUS_CODE IN ('QUEUED','SENDING','SENT','FAILED','BOUNCED','CANCELED'))
);
COMMENT ON TABLE  MAIL_SEND_LOG                 IS '메일 발송 이력';
COMMENT ON COLUMN MAIL_SEND_LOG.SEND_TYPE       IS 'REAL(실발송)/TEST(테스트발송)';
COMMENT ON COLUMN MAIL_SEND_LOG.VERSION_ID      IS '사용 버전 (원문 재현용 스냅샷 키)';
COMMENT ON COLUMN MAIL_SEND_LOG.MERGE_DATA_JSON IS '치환에 사용된 모델 데이터(JSON)';
COMMENT ON COLUMN MAIL_SEND_LOG.SMTP_MESSAGE_ID IS 'SMTP Message-ID';

CREATE INDEX IX_MAIL_LOG_TPL_DT ON MAIL_SEND_LOG (TEMPLATE_ID, REQ_DT);
CREATE INDEX IX_MAIL_LOG_EVT_DT ON MAIL_SEND_LOG (EVENT_ID, REQ_DT);
CREATE INDEX IX_MAIL_LOG_STATUS ON MAIL_SEND_LOG (STATUS_CODE, REQ_DT);
CREATE INDEX IX_MAIL_LOG_TO     ON MAIL_SEND_LOG (TO_EMAIL);

CREATE SEQUENCE SEQ_MAIL_SEND_LOG START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE OR REPLACE TRIGGER TRG_MAIL_SEND_LOG_ID
BEFORE INSERT ON MAIL_SEND_LOG FOR EACH ROW
WHEN (NEW.LOG_ID IS NULL)
BEGIN
    SELECT SEQ_MAIL_SEND_LOG.NEXTVAL INTO :NEW.LOG_ID FROM DUAL;
END;
/

-- 대용량 운영 시 REQ_DT 기준 RANGE 파티셔닝 권장
-- PARTITION BY RANGE (REQ_DT) INTERVAL (NUMTOYMINTERVAL(1,'MONTH')) ( PARTITION P_INIT VALUES LESS THAN (DATE '2026-01-01') )


-- ---------------------------------------------------------------------
-- 9. V_MAIL_DISPATCH_MAP : 발송 매핑 현황 뷰
--    템플릿이 안 붙은 이벤트(발송 시 실패하는 지점)도 LEFT JOIN 으로 노출한다.
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW V_MAIL_DISPATCH_MAP AS
SELECT
    e.EVENT_ID,
    e.EVENT_CODE,
    e.EVENT_NAME,
    e.MODULE_CODE,
    e.TRIGGER_TYPE,
    e.IMPORTANCE,
    e.USE_YN                AS EVENT_USE_YN,
    m.MAP_ID,
    m.LOCALE_CODE,
    m.BRAND_CODE,
    m.VALID_FROM_DT,
    m.VALID_TO_DT,
    m.FROM_EMAIL,
    t.TEMPLATE_ID,
    t.TEMPLATE_CODE,
    t.TEMPLATE_NAME,
    t.CATEGORY_CODE,
    t.ENGINE_TYPE,
    t.STATUS_CODE           AS TEMPLATE_STATUS,
    v.VERSION_NO            AS CURRENT_VERSION_NO,
    v.SUBJECT               AS CURRENT_SUBJECT,
    v.REG_DT                AS VERSION_REG_DT,
    CASE WHEN t.TEMPLATE_ID IS NULL      THEN 'UNMAPPED'
         WHEN t.STATUS_CODE <> 'ACTIVE'  THEN 'INACTIVE_TEMPLATE'
         WHEN NOT EXISTS (SELECT 1 FROM MAIL_EVENT_RECIPIENT r
                           WHERE r.EVENT_ID = e.EVENT_ID AND r.USE_YN = 'Y')
              THEN 'NO_RECIPIENT'
         ELSE 'OK' END      AS BIND_STATUS,
    (SELECT COUNT(*) FROM MAIL_SEND_LOG l
      WHERE l.EVENT_ID = e.EVENT_ID AND l.SEND_TYPE = 'REAL'
        AND l.REQ_DT >= SYSDATE - 30)                                           AS SEND_CNT_30D,
    (SELECT COUNT(*) FROM MAIL_SEND_LOG l
      WHERE l.EVENT_ID = e.EVENT_ID AND l.SEND_TYPE = 'REAL'
        AND l.STATUS_CODE IN ('FAILED','BOUNCED')
        AND l.REQ_DT >= SYSDATE - 30)                                           AS FAIL_CNT_30D,
    (SELECT MAX(l.SENT_DT) FROM MAIL_SEND_LOG l
      WHERE l.EVENT_ID = e.EVENT_ID AND l.SEND_TYPE = 'REAL')                   AS LAST_SENT_DT,
    (SELECT COUNT(*) FROM MAIL_EVENT_RECIPIENT r
      WHERE r.EVENT_ID = e.EVENT_ID AND r.USE_YN = 'Y')                         AS RECIPIENT_RULE_CNT
FROM MAIL_EVENT e
LEFT JOIN MAIL_EVENT_TEMPLATE m
       ON m.EVENT_ID = e.EVENT_ID
      AND m.ACTIVE_YN = 'Y'
      AND (m.VALID_FROM_DT IS NULL OR m.VALID_FROM_DT <= SYSDATE)
      AND (m.VALID_TO_DT   IS NULL OR m.VALID_TO_DT   >= SYSDATE)
LEFT JOIN MAIL_TEMPLATE t
       ON t.TEMPLATE_ID = m.TEMPLATE_ID
      AND t.DEL_YN = 'N'
LEFT JOIN MAIL_TEMPLATE_VERSION v
       ON v.VERSION_ID = t.CURRENT_VERSION_ID;
